import{_ as e,o as s,c as t,a4 as i}from"./chunks/framework.BBs01uty.js";const g=JSON.parse('{"title":"机制四：权限系统（permissions.ts + project-permissions.ts）","description":"","frontmatter":{},"headers":[],"relativePath":"agent-cli/mechanisms/permissions.md","filePath":"agent-cli/mechanisms/permissions.md"}'),d={name:"agent-cli/mechanisms/permissions.md"};function r(a,o,n,c,l,h){return s(),t("div",null,[...o[0]||(o[0]=[i('<h1 id="机制四-权限系统-permissions-ts-project-permissions-ts" tabindex="-1">机制四：权限系统（<code>permissions.ts</code> + <code>project-permissions.ts</code>） <a class="header-anchor" href="#机制四-权限系统-permissions-ts-project-permissions-ts" aria-label="Permalink to &quot;机制四：权限系统（`permissions.ts` + `project-permissions.ts`）&quot;">​</a></h1><blockquote><p>两层：<strong>会话内判定</strong>（<code>permissions.ts</code>，纯函数 + 模式控制器）与<strong>项目级持久化</strong>（<code>project-permissions.ts</code>，落盘 + 信任）。</p></blockquote><h2 id="_1-判定是纯函数" tabindex="-1">1. 判定是纯函数 <a class="header-anchor" href="#_1-判定是纯函数" aria-label="Permalink to &quot;1. 判定是纯函数&quot;">​</a></h2><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">decidePermission</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(meta, args, mode) → { </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;allow&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;deny&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;ask&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, reason</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, mode</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>只读工具元数据 + 参数，<strong>无 IO、无全局状态</strong> —— 所以 AC-31~39 可以直测，不必伪造 LLM 流或起 TUI。</p><ul><li><code>allow</code> → 直接执行</li><li><code>deny</code> → 直接返回拒绝结果（<strong>不弹浮层</strong>），LLM 据此换策略</li><li><code>ask</code> → 走交互审批（<a href="./interaction.html"><code>interaction.md</code></a>）</li></ul><h2 id="_2-四种模式-permissionmode" tabindex="-1">2. 四种模式（<code>PermissionMode</code>） <a class="header-anchor" href="#_2-四种模式-permissionmode" aria-label="Permalink to &quot;2. 四种模式（`PermissionMode`）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>语义</th></tr></thead><tbody><tr><td><code>default</code></td><td>写类 / bash 一律 <code>ask</code>；<strong>非交互下单轮模式自动拒绝</strong>（退出码 2）</td></tr><tr><td><code>acceptEdits</code></td><td>文件编辑自动放行；bash 仍 <code>ask</code></td></tr><tr><td><code>plan</code></td><td>只读：写类直接 <code>deny</code>（AC-34）</td></tr><tr><td><code>bypass</code></td><td>全放行 —— 但<strong>危险命令仍走 <code>forced</code> 强制审批</strong></td></tr></tbody></table><p><code>Shift+Tab</code> 循环切换（AC-20，终端不转发 <code>\\x1bZ</code> 时 <code>/mode</code> 兜底）；<code>PermissionController</code> <strong>按引用</strong>注入 executor，<code>/mode</code> 改的是同一个对象 → 下次工具调用立即生效。状态栏常驻行实时显示当前模式。</p><h2 id="_3-i-3-不变式-安全核心" tabindex="-1">3. I-3 不变式（安全核心） <a class="header-anchor" href="#_3-i-3-不变式-安全核心" aria-label="Permalink to &quot;3. I-3 不变式（安全核心）&quot;">​</a></h2><p><strong><code>ask &amp;&amp; forced</code> 必须在任何授权 / 豁免判定之前短路。</strong></p><ul><li><code>forced</code> 来自<strong>危险命令规则</strong>（<code>rm -fr</code> / <code>rm -rf $HOME</code> / <code>/bin/rm</code> 等正则命中）。</li><li>效果：<code>--yes</code>、<code>bypass</code> 模式、项目级 allow 文件<strong>都不能</strong>自动批准危险命令 —— 必须人工确认（默认高亮&quot;拒绝&quot;）。</li><li>有故障注入反证用例（AC-51）：把 store 提到 <code>forced</code> 之前判定会直接 FAIL。</li></ul><h2 id="_4-审批的-4-选项-ac-21-22" tabindex="-1">4. 审批的 4 选项（AC-21/22） <a class="header-anchor" href="#_4-审批的-4-选项-ac-21-22" aria-label="Permalink to &quot;4. 审批的 4 选项（AC-21/22）&quot;">​</a></h2><p>审批弹层是 questions 引擎的 4 选项（按类型分档）：</p><ul><li><strong>bash</strong>：允许一次 / <strong>永远允许（写入项目权限文件）</strong> / 拒绝 / 拒绝并说明原因</li><li><strong>edit</strong>：允许一次 / <strong>本会话总是允许（仅内存）</strong> / 拒绝 / 拒绝并说明原因</li></ul><p>按类型分档的原因（AC-24）：bash 影响面大 → 落盘可复用；文件编辑影响面小 → 只本会话，<strong>不落盘</strong>。</p><h2 id="_5-项目级权限文件-fr-8" tabindex="-1">5. 项目级权限文件（FR-8） <a class="header-anchor" href="#_5-项目级权限文件-fr-8" aria-label="Permalink to &quot;5. 项目级权限文件（FR-8）&quot;">​</a></h2><p>[<code>project-permissions.ts</code>：</p><ul><li><strong>落点</strong>：<code>&lt;仓库根&gt;/.agent-cli/permissions.json</code>；仓库根 = <code>resolveRepoRoot(cwd)</code>（git 仓库取根，<strong>非 git 回落 cwd</strong>）。</li><li><strong>三态加载</strong>：<code>none</code> / <code>ok</code> / <code>corrupt</code> —— 损坏只告警（AC-52），<strong>不阻断启动</strong>。</li><li><strong>写入</strong>：<code>appendAllowRule</code> 原子写盘（tmp + rename，<strong>立即写</strong>，AC-53），同 <code>firstWord</code> 去重。</li><li><strong>匹配</strong>：<code>commandFirstWord(cmd) === rule.firstWord</code>（<strong>全等</strong>，非前缀 —— <code>ls</code> 不命中 <code>lsblk</code>，AC-46）。保守规则：env 前缀 / 引号 / shell 元字符一律 <code>null</code>；<strong>仅绝对路径取 basename</strong>（<code>/bin/rm</code> ≡ <code>rm</code> 是设计意图），相对路径（<code>./ls</code>、<code>a/../ls</code>）一律拒绝 —— 防仓库内同名脚本&quot;借壳&quot;。</li><li><strong>信任门</strong>：文件内容 hash 存进 <code>user-config.trustedProjects[repoRoot]</code>。首次遇到 → 弹<strong>信任框</strong>（默认高亮&quot;不信任&quot;，<code>--yes</code> 也不自动信任）；未信任 → 规则不生效（相关命令仍逐条询问）。<strong>hash 变化 → 重新询问</strong>（AC-50，含&quot;永远允许写盘后下次启动再弹信任框&quot;的已知取舍，用户裁决保持现状）。</li></ul><h2 id="_6-与-hook-交互的关系" tabindex="-1">6. 与 Hook / 交互的关系 <a class="header-anchor" href="#_6-与-hook-交互的关系" aria-label="Permalink to &quot;6. 与 Hook / 交互的关系&quot;">​</a></h2><ul><li>判定发生在 executor 的第 3 步（PreToolUse hook <strong>之后</strong> —— hook 可先拦，避免无谓弹审批），见 <a href="./tools.html"><code>tools.md</code></a>。</li><li><code>ask</code> 的审批走 <code>interaction.ts</code> 的 <code>requestApproval</code> → 与 <code>ask_user</code> 同一分派路径（AC-27），见 <a href="./interaction.html"><code>interaction.md</code></a>。</li></ul><h2 id="_7-测试" tabindex="-1">7. 测试 <a class="header-anchor" href="#_7-测试" aria-label="Permalink to &quot;7. 测试&quot;">​</a></h2><p><code>permissions.test.ts</code>（判定表 / 模式循环 / I-3 反证 / 会话授权）、<code>project-permissions.test.ts</code>（路径 / 三态 / 原子写 / hash / 首词表）、<code>index.e2e.test.ts</code>（信任框端到端、永远允许立即写盘、<code>--yes</code> 不信任）。</p>',23)])])}const m=e(d,[["render",r]]);export{g as __pageData,m as default};
